import { Card,CardHeader,Image,CardBody } from '@heroui/react'
import React from 'react'

export default function PriceDiscountCard({item,setopenRequiredQuantityModal,setselectedWholesalerReceipt}) {
    const handleSelectDiscount = (item) => {
        setopenRequiredQuantityModal(true);
        setselectedWholesalerReceipt(item.wholesaler_receipt);
      };
  return (
    <Card isPressable className="py-4 h-[340px] w-[300px] m-2 " onPress={()=>handleSelectDiscount(item)}>
      <CardHeader className="pb-0 pt-2 px-4 flex-col items-start">
        <p className="text-tiny uppercase font-bold">  {item.wholesaler_receipt_title}</p>
        <small className="text-default-500">Offer Ends on {item.end}</small>
        <h4 className="font-bold text-large">{item.title}</h4>
      </CardHeader>
      <CardBody className="overflow-visible py-2">
        <Image
          alt={item.title}
          className="object-cover rounded-xl"
          src={
            item.price_discount_banners &&
              item.price_discount_banners.length
              ? item.price_discount_banners[0].price_discount_banner
              : ""}
          width={270}
         
     
        />
      </CardBody>
  </Card>
  )
}
